from pwn import *
import sys

host = 'misc.chal.csaw.io'
port = 9998

expressions = ['0/0', "float('inf')", str(9999999999999*9999999999999)]

# For consistent output, and avoid colors
context(log_level='error')

def try_expression(expr):
    output = ''
    try:
        r = remote(host, port, timeout=5)
        # Wait for prompt (assume at most two lines):
        lines = []
        for _ in range(2):
            try:
                l = r.recvline(timeout=2)
                if l: lines.append(l.decode(errors='replace'))
            except EOFError:
                break
        # Send expression
        r.sendline(expr.encode())
        # Read the next few lines for result or error
        while True:
            try:
                l = r.recv(timeout=2)
                if l:
                    output += l.decode(errors='replace')
                else:
                    break
            except EOFError:
                break
        r.close()
    except Exception as e:
        output += f'Exception connecting or reading: {str(e)}\n'
    return output

results = {}
for e in expressions:
    results[e] = try_expression(e)

# Dump findings in clear text
for e, o in results.items():
    print(f'--- Expression: {e!r} ---')
    print(o)
    print('--- END ---\n')

